code = r'''
import base64
from dataclasses import dataclass
from io import BytesIO
from pathlib import Path
import json
import math

import numpy as np
import pandas as pd
import plotly.graph_objects as go


@dataclass(frozen=True)
class ShockPoint:
    date: pd.Timestamp
    prev_price: float
    price: float
    change_abs: float
    change_pct: float


def _read_inputs():
    task = json.loads(Path('benchmark/task_input.json').read_text())
    brief_md = Path('benchmark/source_brief.md').read_text(encoding='utf-8')
    df = pd.read_csv('benchmark/data.csv')
    return task, brief_md, df


def _prepare_df(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    if 'Date' not in df.columns:
        raise ValueError('Expected Date column')
    price_col = 'Crude_Oil_Price'
    if price_col not in df.columns:
        # fallback: first non-Date column
        candidates = [c for c in df.columns if c.lower() != 'date']
        if not candidates:
            raise ValueError('No price column found')
        price_col = candidates[0]
        df = df.rename(columns={price_col: 'Crude_Oil_Price'})

    df['Date'] = pd.to_datetime(df['Date'])
    df['Crude_Oil_Price'] = pd.to_numeric(df['Crude_Oil_Price'], errors='coerce')
    df = df.dropna(subset=['Date', 'Crude_Oil_Price']).sort_values('Date').reset_index(drop=True)

    df['Year'] = df['Date'].dt.year
    df['Month'] = df['Date'].dt.month
    df['Decade'] = (df['Year'] // 10) * 10
    df['Decade_Label'] = df['Decade'].astype(str) + 's'

    df['MoM_Abs'] = df['Crude_Oil_Price'].diff()
    df['MoM_Pct'] = df['Crude_Oil_Price'].pct_change() * 100.0

    df['YoY_Abs'] = df['Crude_Oil_Price'].diff(12)
    df['YoY_Pct'] = df['Crude_Oil_Price'].pct_change(12) * 100.0

    df['Roll12_Std'] = df['Crude_Oil_Price'].rolling(12).std(ddof=1)
    return df


def _cagr(first_date: pd.Timestamp, last_date: pd.Timestamp, first_price: float, last_price: float) -> float:
    years = (last_date - first_date).days / 365.25
    if years <= 0:
        return float('nan')
    if first_price <= 0 or last_price <= 0:
        return float('nan')
    return (last_price / first_price) ** (1.0 / years) - 1.0


def _format_usd(x: float) -> str:
    return f"${x:,.2f}"


def _format_pct(x: float) -> str:
    if pd.isna(x):
        return '—'
    return f"{x:,.2f}%"


def _plot_full_series(df: pd.DataFrame) -> str:
    fig = go.Figure()
    fig.add_trace(
        go.Scatter(
            x=df['Date'],
            y=df['Crude_Oil_Price'],
            mode='lines',
            name='Crude oil price (USD/bbl)',
            line=dict(color='#1f77b4', width=2),
            hovertemplate='%{x|%Y-%m}: $%{y:,.2f}<extra></extra>',
        )
    )

    max_idx = df['Crude_Oil_Price'].idxmax()
    min_idx = df['Crude_Oil_Price'].idxmin()

    for idx, label, color in [
        (min_idx, 'All-time low', '#2ca02c'),
        (max_idx, 'All-time high', '#d62728'),
    ]:
        fig.add_trace(
            go.Scatter(
                x=[df.loc[idx, 'Date']],
                y=[df.loc[idx, 'Crude_Oil_Price']],
                mode='markers+text',
                name=label,
                marker=dict(size=10, color=color),
                text=[label],
                textposition='top center',
                hovertemplate='%{x|%Y-%m}: $%{y:,.2f}<extra></extra>',
            )
        )

    fig.update_layout(
        height=420,
        margin=dict(l=40, r=20, t=40, b=40),
        xaxis_title='Month',
        yaxis_title='USD per barrel',
        template='plotly_white',
        legend=dict(orientation='h', yanchor='bottom', y=1.02, xanchor='left', x=0),
    )

    return fig.to_html(full_html=False, include_plotlyjs=False)


def _plot_decade_bars(decade_stats: pd.DataFrame) -> str:
    decade_stats = decade_stats.copy()
    decade_stats['Decade_Label'] = decade_stats['Decade'].astype(int).astype(str) + 's'

    fig = go.Figure()
    fig.add_trace(
        go.Bar(
            x=decade_stats['Decade_Label'],
            y=decade_stats['Mean'],
            name='Mean',
            marker_color='#1f77b4',
            hovertemplate='%{x}: $%{y:,.2f}<extra></extra>',
        )
    )
    fig.update_layout(
        height=340,
        margin=dict(l=40, r=20, t=30, b=40),
        xaxis_title='Decade',
        yaxis_title='Mean price (USD/bbl)',
        template='plotly_white',
    )
    return fig.to_html(full_html=False, include_plotlyjs=False)


def _plot_volatility_roll12(df: pd.DataFrame) -> str:
    fig = go.Figure()
    fig.add_trace(
        go.Scatter(
            x=df['Date'],
            y=df['Roll12_Std'],
            mode='lines',
            name='12m rolling std dev',
            line=dict(color='#9467bd', width=2),
            hovertemplate='%{x|%Y-%m}: %{y:,.2f}<extra></extra>',
        )
    )
    fig.update_layout(
        height=320,
        margin=dict(l=40, r=20, t=30, b=40),
        xaxis_title='Month',
        yaxis_title='Rolling 12m std dev (USD/bbl)',
        template='plotly_white',
        showlegend=False,
    )
    return fig.to_html(full_html=False, include_plotlyjs=False)


def _plot_histogram(df: pd.DataFrame) -> str:
    fig = go.Figure()
    fig.add_trace(
        go.Histogram(
            x=df['Crude_Oil_Price'],
            nbinsx=40,
            marker_color='#17becf',
            hovertemplate='Price bin: $%{x}<br>Count: %{y}<extra></extra>',
        )
    )
    fig.update_layout(
        height=320,
        margin=dict(l=40, r=20, t=30, b=40),
        xaxis_title='Price (USD/bbl)',
        yaxis_title='Number of months',
        template='plotly_white',
        showlegend=False,
    )
    return fig.to_html(full_html=False, include_plotlyjs=False)


def _shock_from_idx(df: pd.DataFrame, idx: int, kind: str) -> ShockPoint:
    if kind == 'mom':
        change_abs = float(df.loc[idx, 'MoM_Abs'])
        change_pct = float(df.loc[idx, 'MoM_Pct'])
    elif kind == 'yoy':
        change_abs = float(df.loc[idx, 'YoY_Abs'])
        change_pct = float(df.loc[idx, 'YoY_Pct'])
    else:
        raise ValueError('kind must be mom or yoy')

    prev = float(df.loc[idx - (1 if kind == 'mom' else 12), 'Crude_Oil_Price'])
    cur = float(df.loc[idx, 'Crude_Oil_Price'])
    return ShockPoint(
        date=pd.Timestamp(df.loc[idx, 'Date']),
        prev_price=prev,
        price=cur,
        change_abs=change_abs,
        change_pct=change_pct,
    )


def _build_report(task: dict, brief_md: str, df: pd.DataFrame) -> str:
    title = task['brief']['title']

    first_date = df['Date'].iloc[0]
    last_date = df['Date'].iloc[-1]
    first_price = float(df['Crude_Oil_Price'].iloc[0])
    last_price = float(df['Crude_Oil_Price'].iloc[-1])

    overall_min = float(df['Crude_Oil_Price'].min())
    overall_max = float(df['Crude_Oil_Price'].max())
    overall_min_date = df.loc[df['Crude_Oil_Price'].idxmin(), 'Date']
    overall_max_date = df.loc[df['Crude_Oil_Price'].idxmax(), 'Date']

    price_range = overall_max - overall_min
    cagr = _cagr(first_date, last_date, first_price, last_price)
    vol_std = float(df['Crude_Oil_Price'].std(ddof=1))

    # Max MoM absolute and percent (by absolute percent)
    max_mom_abs_idx = int(df['MoM_Abs'].abs().idxmax())
    max_mom_pct_idx = int(df['MoM_Pct'].abs().idxmax())
    max_yoy_abs_idx = int(df['YoY_Abs'].abs().idxmax())
    max_yoy_pct_idx = int(df['YoY_Pct'].abs().idxmax())

    mom_abs_shock = _shock_from_idx(df, max_mom_abs_idx, 'mom')
    mom_pct_shock = _shock_from_idx(df, max_mom_pct_idx, 'mom')
    yoy_abs_shock = _shock_from_idx(df, max_yoy_abs_idx, 'yoy')
    yoy_pct_shock = _shock_from_idx(df, max_yoy_pct_idx, 'yoy')

    decade_stats = (
        df.groupby('Decade', as_index=False)
