            Mean=('Crude_Oil_Price', 'mean'),
            StdDev=('Crude_Oil_Price', lambda s: float(pd.Series(s).std(ddof=1))),
            Min=('Crude_Oil_Price', 'min'),
            Max=('Crude_Oil_Price', 'max'),
            Months=('Crude_Oil_Price', 'size'),
        )
